/* ============ STORY THREAD 5 — THE LONG NIGHT: A LAND DREADNOUGHT CALLED THE LAST SERMON IS COMING DOWN HARROW VALE, AND EVERYBODY YOU HAVE EVER HELPED IS ABOUT TO BE ASKED FOR SOMETHING ============ */
Object.assign(CAST, { 9181: { build: 'slim', h: 1.7, habit: 'back', ...stLook('#e8e8e8', 3, '') }, 9183: { build: 'broad', h: 1.93, habit: 'hips' }, 9185: { build: 'slim', h: 1.84, habit: 'cross', ...stLook('#1b1b1b', 0, 'glasses') } });
/* somebody the story needs tomorrow: at a quarter armour they are out of the fight, not out of the story */
function stKeep(e, who, line) { stTick(() => { if (MS.over || e.dead) return false; if (e.hp > e.max * .25) return true; Object.assign(e, { inv: true, pacify: true, ai: 'hold', out: true, team: 2, tgt: null });   /* neutral, so that nobody wastes the night shooting at them */ msg(`${e.name} IS OUT OF THE FIGHT`, 3); if (who && line) chatter(who, line); return false; }); return e; }
