      await after(2.5); look(S.post, 'INCOMING'); await tell(xo, 'Those are the big shells and they are walking in on the post. That is ranging fire — whoever it is has an observer. Stay off the rings and stay near the trucks.');
      const w2 = stFrom(.8, S.post, 2.2, 230, { focus: Tk[1] }); await stHold('h', S.post, 90, 40, 'Cover the trucks while they load'); await until(() => alive(w2) <= 1);
