      stTick(() => { if (ms.over) return false; const L0 = lead(), jam = FD.t0.some(e => e.team === 1 && e.kind !== 'struct' && !e.dread && stDist(e.pos, L0.pos) < 80) || !near(L0.pos, 190); Tk.forEach(t => { t.halt = jam; }); return true; });
      Tk.forEach((t, i) => nav('t' + i, t, 'TRUCK', '#8dff6a')); setObj('c', () => `Escort the trucks to the evac field — ${3 - lost}/3 rolling · ${Math.round(stDist(lead().pos, S.lz) / 10) * 10} m`); B.ai = 'follow'; for (const e of Mi) e.ai = 'follow';
      await tell(brick, "Loaded! Trucks go when you're close and stop when they're shot at — they're farm lads, not heroes. I'll bring up the back. Mind the ford, it's where I'd put an ambush, and I'm an idiot.");
      await until(() => stDist(lead().pos, S.post) > 260);
